interface.definition:
#"SYSTEM_SYSRULES_formLayout_v2"(
  titleBar: #"SYSTEM_SYSRULES_headerTemplateSimple"(
    title: "Retire Vehicle Confirmation",
    titleColor: "STANDARD",
    secondaryTextColor: "SECONDARY",
    stampIcon: "car-side",
    stampColor: "ACCENT"
  ),
  showTitleBarDivider: false,
  contents: {
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          labelPosition: "COLLAPSED",
          value: {
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: "Are you sure you want to retire this ",
              size: "MEDIUM_PLUS"
             ),
             #"SYSTEM_SYSRULES_richTextItem_v1"(
               text: a!defaultValue(ri!vehicle[#"urn:appian:record-field:v1:4319b3e4-ca07-43be-8557-19466417914e/631cfde1-92e4-4591-8983-a04047641399"] & " " & ri!vehicle[#"urn:appian:record-field:v1:4319b3e4-ca07-43be-8557-19466417914e/78897d20-5972-4a74-a3a9-eab648787758"] & " " & ri!vehicle[#"urn:appian:record-field:v1:4319b3e4-ca07-43be-8557-19466417914e/9a7bf720-51c2-4ea5-9a1c-707c3c3c6778"], ""),
               size: "MEDIUM_PLUS",
               style: {
                 "STRONG"
               }
             ),
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: {" ?"},
              size: "MEDIUM_PLUS"
            )
          },
          align: "CENTER"
        )
      }
    )
  },
  buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
    primaryButtons: {
      #"SYSTEM_SYSRULES_buttonWidget_v1"(
        label: "Yes, Retire",
        submit: true,
        style: "SOLID",
        loadingIndicator: true
      )
    },
    secondaryButtons: {
      #"SYSTEM_SYSRULES_buttonWidget_v1"(
        label: "Cancel",
        value: true,
        saveInto: ri!cancel,
        submit: true,
        style: "OUTLINE",
        validate: false
      )
    }
  )
)
